scenarios.example_code:
// mobile client:
const caps = await fetch('/api/hdk/map/capabilities').then(r => r.json());
if (caps.offline_tiles) { enableOfflineTilePrefetch(); }

import { switchProvider } from '@projexlight/hdk-map';
await switchProvider({
  tenant_id, new_provider: 'mapbox-v11',
  reason: 'google-billing-increase-2026-05',
  operator_persona_id,
});

// driven by the daily quota check:
if (consumed_pct > HDK_MAP_TILE_QUOTA_WARN_PCT) {
  emitEvent('hdk-map.tiles.quota.warn.v1', { provider, consumed_pct, days_remaining });
}

// mobile client:
if (caps.offline_tiles && route.has_low_signal_areas) {
  await prefetchTilesForBoundingBox(route.bbox, { max_zoom: 16 });
}
